<?php
declare(strict_types=1);require dirname(__DIR__).'/app/Core/PublicPage.php';require dirname(__DIR__).'/app/Core/Database.php';$rows=[];$error=null;
try{$db=Database::connection();$q=$db->query("SELECT slug,title,summary,published_at FROM content_items WHERE status='PUBLISHED' AND content_type IN ('ANNOUNCEMENT','NOTICE','ARTICLE') ORDER BY published_at DESC LIMIT 50");$rows=$q->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){error_log('Announcements: '.$e->getMessage());$error='Announcements are temporarily unavailable.';}
pageHeader('Community Updates','Verified public announcements and community notices from Barangay San Antonio.');?>
<main id="main-content"><section class="page-hero"><div class="page-hero-inner"><div class="breadcrumb"><a href="<?= Security::e(url()) ?>">Home</a> / Community Updates</div><p class="eyebrow">NEWS AND INFORMATION</p><h1>Community Updates</h1><p>Official notices and announcements appear here after review and publication by authorized barangay personnel.</p></div></section><section class="section"><?php if($error): ?><div class="notice warning"><?= Security::e($error) ?></div><?php elseif(!$rows): ?><div class="publication-empty"><h2>No verified announcements have been published</h2><p>Please check back after authorized barangay personnel publish an update.</p></div><?php else: ?><div class="civic-grid"><?php foreach($rows as $r): ?><article class="civic-card"><p class="eyebrow">PUBLIC NOTICE · <?= Security::e($r['published_at']) ?></p><h2><?= Security::e($r['title']) ?></h2><p><?= Security::e($r['summary']??'') ?></p><a class="learn" href="<?= Security::e(url('article.php?slug='.$r['slug'])) ?>">Read announcement →</a></article><?php endforeach; ?></div><?php endif; ?></section></main><?php pageFooter();
